  async function checkRoadmapSignals(force){const box=$('#roadmap-signal-output');if(!box||roadmapPulseChecking)return;const last=+(localStorage.getItem('arise.roadmap-pulse.last')||0);if(!force&&Date.now()-last<6*3600000){const cache=localStorage.getItem('orbit.signals.cache');if(cache){try{const d=JSON.parse(cache);showPulse(d.items||[],d.updatedAt);return}catch(_){}}}roadmapPulseChecking=true;box.innerHTML='<div class="live-loading">Checking recent AI, data science and engineering feeds for corroborated changes…</div>';try{const r=await fetch('/api/signals',{cache:'no-store'});if(!r.ok)throw new Error('offline');const d=await r.json();signalsCache=d.items||[];localStorage.setItem('orbit.signals.cache',JSON.stringify(d));localStorage.setItem('arise.roadmap-pulse.last',String(Date.now()));showPulse(d.items||[],d.updatedAt)}catch(e){const cache=localStorage.getItem('orbit.signals.cache');if(cache){const d=JSON.parse(cache);showPulse(d.items||[],d.updatedAt);box.insertAdjacentHTML('afterbegin','<p class="muted small">Offline: showing saved feed evidence.</p>')}else box.innerHTML='<div class="pulse-quiet">No saved feed is available. Connect to the ARISE server to check current sources.</div>'}finally{roadmapPulseChecking=false}}
