    tasks.forEach(function(task){let rem=task.duration,block=1;while(rem>0){let length=Math.min(50,rem);if(rem>50&&rem-50<15)length=Math.ceil(rem/2);let moved=true,guard=0;while(moved&&guard++<80){moved=false;if(cursor+length>endMins){unscheduled.push(task.title);break}const collision=busy.find(function(x){return cursor<x.end&&cursor+length>x.start});if(collision){cursor=collision.end+breakMins;moved=true}}if(cursor+length>endMins)break;const hh=String(Math.floor(cursor/60)).padStart(2,'0'),mm=String(cursor%60).padStart(2,'0');const isCollege=/math|physics|chem|exam|college|syllabus/i.test(task.title),isCode=/code|program|python|c\+\+|java|javascript|sql|dsa|problem|algorithm/i.test(task.title);state.sessions.push({id:uid(),title:task.title+(task.duration>50?' · focus '+block:''),date:date,time:hh+':'+mm,duration:length,track:isCollege?'College exam':isCode?'DSA':'Other',note:'Generated by ARISE timetable builder',done:false,source:'arise-timetable'});busy.push({start:cursor,end:cursor+length});cursor+=length;rem-=length;block++;placed++;breakCount++;if(rem>0||breakCount%3===0)cursor+=breakCount%3===0?25:breakMins}});
    selectedDate=date;weekOffset=Math.round((weekStart(new Date(date+'T00:00'))-weekStart(new Date()))/604800000);save();renderPlanner();renderHome();renderYearCalendar();
    const unique=Array.from(new Set(unscheduled));$('#timetable-feedback').textContent=placed+' focused block'+(placed===1?'':'s')+' placed for '+new Date(date+'T00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short'})+'.'+(unique.length?' Could not fit: '+unique.join(', ')+'. Extend the day or lower task durations.':' Your saved sessions were kept; breaks are included.');toast('Your day timetable is ready.');
