  function renderTimer(){const m=Math.floor(timerSeconds/60),s=timerSeconds%60;$('#timer-face').textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');$('#timer-progress').style.width=((1500-timerSeconds)/1500*100)+'%';$('#timer-toggle').textContent=timerHandle?'Pause focus':'Start focus'}
