  let noteDbPromise=null,notesCache=[],selectedNoteId='',noteFilter='All',noteCollectionFilter='All',noteSaveTimer=null;
  function openNoteDb(){if(noteDbPromise)return noteDbPromise;noteDbPromise=new Promise(function(resolve){if(!window.indexedDB){resolve(null);return}const req=indexedDB.open('orbit-notes-v1',1);req.onupgradeneeded=function(){const db=req.result;if(!db.objectStoreNames.contains('notes'))db.createObjectStore('notes',{keyPath:'id'})};req.onsuccess=function(){resolve(req.result)};req.onerror=function(){resolve(null)}});return noteDbPromise}
