  let roomCode='',roomName=state.profile.name||'Vidwath',roomEventSource=null,roomSnapshot=null;
  async function roomRequest(path,method,body){const r=await fetch('/api/rooms'+path,{method:method||'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'Room request failed');return d}
