    $('#room-note-save').addEventListener('click',async function(){await roomRequest('/'+encodeURIComponent(roomCode)+'/notes','PUT',{notes:$('#room-note-input').value});toast('Shared notes saved.')});
    box.querySelector('[data-room-copy]').addEventListener('click',async function(){await navigator.clipboard.writeText(roomCode);toast('Invite code copied.')});box.querySelector('[data-room-leave]').addEventListener('click',leaveRoom);
