  async function joinRoom(code,name){roomName=(name||roomName).slice(0,32);roomCode=String(code).toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8);if(!roomCode)throw new Error('Enter a room code.');roomSnapshot=await roomRequest('/'+encodeURIComponent(roomCode)+'/join','POST',{name:roomName});if(roomEventSource)roomEventSource.close();roomEventSource=new EventSource('/api/rooms/'+encodeURIComponent(roomCode)+'/events');roomEventSource.onmessage=function(e){try{roomSnapshot=JSON.parse(e.data);roomRender()}catch(_){}};roomRender();}
  async function sendRoomNote(text){if(roomCode)await roomRequest('/'+encodeURIComponent(roomCode)+'/messages','POST',{name:roomName,text:String(text).slice(0,500)})}
  function leaveRoom(){if(roomEventSource)roomEventSource.close();roomEventSource=null;roomCode='';roomSnapshot=null;$('#room-workspace').classList.add('hidden');$('#room-lobby').classList.remove('hidden')}
  $('#create-room-form').addEventListener('submit',async function(e){e.preventDefault();const f=new FormData(e.currentTarget),name=f.get('name').trim(),title=f.get('title').trim();try{const r=await roomRequest('','POST',{name,title});await joinRoom(r.code,name)}catch(err){toast(err.message+' · Start the app server first.')}});
  $('#join-room-form').addEventListener('submit',async function(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await joinRoom(f.get('code'),f.get('name').trim())}catch(err){toast(err.message)}});

