  function findLocalAnswer(q){const words=q.toLowerCase().split(/[^a-z0-9+#]+/).filter(function(x){return x.length>2}),matches=[];D.langCourses.forEach(function(c){c.topics.forEach(function(t){const text=(c.name+' '+t.name).toLowerCase();const score=words.reduce(function(n,w){return n+(text.includes(w)?1:0)},0);if(score)matches.push({score,title:c.name+' · '+t.name,video:t.video,notes:t.notes,picks:t.picks})})});D.topics.forEach(function(t){const text=(t.title+' '+t.desc+' '+t.track).toLowerCase(),score=words.reduce(function(n,w){return n+(text.includes(w)?1:0)},0);if(score)matches.push({score,title:t.title,video:t.video,notes:t.notes,picks:D.problemPicks[t.id]||[]})});return matches.sort(function(a,b){return b.score-a.score}).slice(0,4)}
