  const mentorSkills={beginner:[['Programming & data','Keep learning C, then add Python. Practice variables, loops, functions, arrays, NumPy and pandas.','https://www.kaggle.com/learn/python','https://www.kaggle.com/learn/pandas'],['Math & statistics','Build comfort with algebra, vectors, probability, distributions and descriptive statistics.','https://www.3blue1brown.com/topics/linear-algebra','https://www.khanacademy.org/math/statistics-probability'],['First ML models','Learn train/test splits, regression, classification, metrics and data leakage.','https://developers.google.com/machine-learning/crash-course','https://www.kaggle.com/learn/intro-to-machine-learning']],intermediate:[['Machine learning','Compare baseline models, feature engineering, cross-validation and error analysis with scikit-learn.','https://scikit-learn.org/stable/tutorial/index.html','https://www.kaggle.com/learn/intermediate-machine-learning'],['Deep learning','Understand tensors, backpropagation, optimizers, regularization and transfer learning.','https://course.fast.ai/','https://pytorch.org/tutorials/'],['NLP & computer vision','Learn tokenization, embeddings, transformers, image augmentation and evaluation.','https://huggingface.co/learn/nlp-course/','https://huggingface.co/learn/computer-vision-course/']],advanced:[['Prompt engineering & LLM systems','Design structured prompts, tool calls, retrieval, citations and evaluations; measure failure cases.','https://platform.openai.com/docs/guides/prompt-engineering','https://huggingface.co/learn/agents-course/'],['Production ML & data engineering','Build reproducible pipelines, tests, monitoring, model serving and data quality checks.','https://madewithml.com/','https://docs.getdbt.com/docs/introduction'],['Research & specialization','Reproduce a paper, publish a careful benchmark, and specialize in NLP, CV, multimodal or AI safety.','https://paperswithcode.com/','https://huggingface.co/learn'] ]};
