  function mentorModuleHtml(module,level){let body='',title='',sub='';
    if(module==='skills'){title='Skills Hub';sub='Build foundations in order. Since you are in first year and studying C, keep problem solving and math steady while you add Python for data work.';const rows=mentorSkills[level];body='<div class="mentor-step-list">'+rows.map(function(x,i){return '<article class="mentor-step"><span class="mentor-step-number">0'+(i+1)+'</span><div><h4>'+esc(x[0])+'</h4><p>'+esc(x[1])+'</p><div class="mentor-card-links">'+link(x[2],'Start learning ↗')+' '+link(x[3],'Practice / reference ↗')+'</div></div></article>'}).join('')+'</div><div class="mentor-callout"><b>Core skill map</b><p>Python · statistics · SQL · machine learning · deep learning · NLP · computer vision · prompt engineering · evaluation · data pipelines · communication.</p></div><button class="mentor-action-button" data-mentor-action="ai-roadmap">Build this as a side roadmap →</button><button class="mentor-action-button secondary" data-mentor-action="open-learn">Open all learning paths →</button>'}
    if(module==='courses'){title='Courses Hub';sub='A focused shortlist; choose one main course and finish its projects before collecting more certificates.';const courses=[['Machine Learning Specialization · DeepLearning.AI / Stanford Online','Beginner → intermediate · Supervised learning, trees, neural networks and practical model evaluation. A strong first structured ML course.','https://www.coursera.org/specializations/machine-learning-introduction','Coursera'],['CS50’s Introduction to Artificial Intelligence with Python · Harvard','Intermediate · Search, optimization, learning, neural networks and language. Useful after Python basics and introductory programming.','https://cs50.harvard.edu/ai/','edX / Harvard'],['Practical Deep Learning for Coders · fast.ai','Intermediate · Build practical vision, NLP and tabular models, then study the foundations behind them. Project-heavy and free to audit.','https://course.fast.ai/','fast.ai'],['IBM AI Engineering Professional Certificate','Intermediate · A guided sequence through ML, deep learning, PyTorch and deployment concepts. Useful for a structured portfolio path.','https://www.coursera.org/professional-certificates/ai-engineer','Coursera'],['Udemy: practical Python / machine learning catalog','Beginner → intermediate · Compare current syllabi, update dates and project examples before enrolling; course quality and pricing vary by instructor.','https://www.udemy.com/courses/search/?q=python%20machine%20learning','Udemy'],['Data Science / AI courses on edX','Beginner → advanced · Browse university courses, check prerequisites and audit availability; choose statistics and Python foundations first.','https://www.edx.org/learn/data-science','edX']];body='<div class="mentor-course-grid">'+courses.map(function(x){return mentorCard(x[0],x[1],[[x[2],'Open '+x[3]]])}).join('')+'</div><div class="mentor-callout"><b>Suggested sequence for you</b><p>Finish C control flow and functions → learn Python basics → statistics and pandas → first ML course → one end-to-end project. You can study college maths alongside this path.</p></div><button class="mentor-action-button" data-mentor-action="open-learn">Open ARISE topic lectures, notes & practice →</button>'}
    if(module==='hackathons'){title='Hackathons & Events Hub';sub='Upcoming public listings saved by ARISE. Deadlines and eligibility change—open the organizer page before committing.';let events=[];try{events=JSON.parse(localStorage.getItem('orbit.hackathons.cache')||'[]')}catch(_){}events=events.filter(function(x){return !x.endDate||x.endDate>=today}).slice(0,5);body=events.length?'<div class="mentor-event-list">'+events.map(function(x){const when=x.dateLabel||((x.startDate||x.endDate)?[x.startDate,x.endDate].filter(Boolean).join(' – '):'Check event page');return '<article class="mentor-event"><span class="mentor-event-date">'+esc(when)+'</span><div><h4>'+esc(x.title)+'</h4><p>'+esc([x.source||'Event listing',x.theme||x.description||'',x.eligibility||'Confirm eligibility with organizer'].filter(Boolean).join(' · '))+'</p>'+link(x.url,'Organizer & registration ↗')+'</div></article>'}).join('')+'</div>':'<div class="mentor-callout"><b>No cached listings yet</b><p>Connect to the ARISE server to refresh current event cards; organizer directories are still available below.</p></div>';body+='<div class="mentor-card-links">'+link('https://devpost.com/c/artificial-intelligence','Devpost AI challenges ↗')+link('https://devfolio.co/hackathons','Devfolio India hackathons ↗')+link('https://unstop.com/hackathons','Unstop India hackathons ↗')+link('https://mlh.io/seasons/2026/events','MLH events ↗')+link('https://www.kaggle.com/competitions','Kaggle competitions ↗')+'</div><button class="mentor-action-button" data-mentor-action="refresh-hackathons">↻ Refresh event listings</button><button class="mentor-action-button secondary" data-mentor-action="open-hackathons">Open hackathon radar →</button>'}
    if(module==='market'){title='AI Market Hub';sub='Combine employer skill reports, project ecosystem changes, live job-board examples and engineering news. A job-feed sample is a signal, not a full India market census.';let data={};try{data=JSON.parse(localStorage.getItem('orbit.signals.cache')||'{}')}catch(_){}const m=data.market||{},top=(m.skills||[]).slice(0,6);body='<div class="mentor-market-evidence"><article><span class="eyebrow">HIRING SKILLS SIGNAL · 2026</span><p>LinkedIn’s 2026 Skills on the Rise highlights AI/LLM skills alongside communication, leadership and responsible AI skills. Pair technical work with clear explanations and evidence.</p>'+link('https://news.linkedin.com/2026/Skills-on-the-rise-2026','Read LinkedIn report ↗')+'</article><article><span class="eyebrow">BUILDER ECOSYSTEM · 2025</span><p>GitHub Octoverse tracks AI project growth and language/tool changes. Use this as a developer ecosystem signal; learn typed, tested, deployable software alongside AI fundamentals.</p>'+link('https://octoverse.github.com/','Read GitHub Octoverse ↗')+'</article></div>'+(top.length?'<div class="mentor-market-sample"><div class="eyebrow">LIVE JOB-BOARD SAMPLE · '+esc(m.jobsSampled||0)+' LISTINGS · '+esc(m.locationScope||'global remote sample')+'</div>'+top.map(function(s){return '<article class="mentor-market-row"><b>'+esc(s.name)+'</b><span>'+esc(s.count)+' mentions</span><div>'+((s.jobs||[]).slice(0,2).map(function(j){return link(j.url,esc(j.company?j.company+' · ':'')+esc(j.title)+' ↗')}).join(' ')||'')+'</div></article>'}).join('')+'<small>Source: '+esc(m.source||'RemoteOK')+' · refreshed '+esc(m.updatedAt?new Date(m.updatedAt).toLocaleString('en-IN'):'when feed last loaded')+'. Counts overlap when a job mentions multiple skills.</small></div>':'<div class="mentor-callout"><b>Live job sample not cached yet</b><p>Refresh Market News to load the latest available public listings and community feed.</p></div>')+'<div class="mentor-callout"><b>Opportunities to turn signals into proof</b><p>Research: reproduce a small paper result. Product: build a user-tested AI feature with evaluations. Entrepreneurship: find a local workflow pain point, interview users, and prototype the smallest useful solution.</p></div><button class="mentor-action-button" data-mentor-action="refresh-market">↻ Refresh job & community signals</button><button class="mentor-action-button secondary" data-mentor-action="open-signals">Open Market News →</button>'}
    return '<div class="mentor-module-heading"><span class="eyebrow">ARISE · '+esc(module.toUpperCase())+'</span><h3>'+esc(title)+'</h3><p>'+esc(sub)+'</p></div>'+(module==='skills'?mentorLevelButtons(module,level):'')+body+'<div class="mentor-next"><b>Want a more personal answer?</b><p>Tell me your level, time per week, and what you want to build—or ask a follow-up below.</p></div>';
  }
  function showMentorModule(module,level){const name={skills:'Skills',courses:'Courses',hackathons:'Hackathons',market:'Market News'}[module]||'Explore';appendAssistant(name,'user');const card=appendAssistant('', 'bot',mentorModuleHtml(module,level||'beginner'));$('#assistant-status').textContent='ARISE learning guide · '+(module==='market'?'live-aware':'ready');return card}
  function buildLiveContext(){let signalData={},events=[];try{signalData=JSON.parse(localStorage.getItem('orbit.signals.cache')||'{}')}catch(_){}try{events=JSON.parse(localStorage.getItem('orbit.hackathons.cache')||'[]')}catch(_){}return {market:signalData.market?{source:signalData.market.source,updatedAt:signalData.market.updatedAt,locationScope:signalData.market.locationScope,skills:(signalData.market.skills||[]).slice(0,8).map(function(x){return {name:x.name,count:x.count}})}:null,signals:(signalData.items||[]).slice(0,8).map(function(x){return {title:x.title,source:x.source,date:x.published,url:x.url}}),hackathons:events.slice(0,8).map(function(x){return {title:x.title,source:x.source,startDate:x.startDate,endDate:x.endDate,url:x.url}})}}
  function openAssistant(){ $('#assistant-panel').classList.add('open');$('#assistant-fab').classList.add('hidden');$('#assistant-context-label').textContent='Search ARISE or choose a guided mentor hub below.';setTimeout(function(){$('#assistant-form textarea').focus()},100)}
