  $('#assistant-messages').addEventListener('click',function(e){const moduleButton=e.target.closest('[data-mentor-module]');if(moduleButton){const module=moduleButton.dataset.mentorModule,level=moduleButton.dataset.mentorLevel||'beginner',card=showMentorModule(module,level);if(module==='hackathons')loadHackathons().then(function(){if(card.isConnected)card.innerHTML=mentorModuleHtml(module,level)});if(module==='market')loadSignals().then(function(){if(card.isConnected)card.innerHTML=mentorModuleHtml(module,level)});return}const action=e.target.closest('[data-mentor-action]');if(action){const a=action.dataset.mentorAction;if(a==='ai-roadmap'){navTo('career');$('#roadmap-track').value='ai';fillRoadmapForm('ai');$('#roadmap-title').value='AI & Data Science skill path';toast('Review the suggested topics, then create your separate side roadmap.')}else if(a==='open-learn')navTo('learn');else if(a==='open-hackathons')navTo('hackathons');else if(a==='open-signals')navTo('signals');else if(a==='refresh-hackathons'){const card=action.closest('.assistant-message');action.disabled=true;action.textContent='Refreshing…';loadHackathons().then(function(){if(card&&card.isConnected)card.innerHTML=mentorModuleHtml('hackathons','beginner')})}else if(a==='refresh-market'){const card=action.closest('.assistant-message');action.disabled=true;action.textContent='Refreshing…';loadSignals().then(function(){if(card&&card.isConnected)card.innerHTML=mentorModuleHtml('market','beginner')})}return}const b=e.target.closest('[data-mentor-ask]');if(b){$('#assistant-form textarea').value=b.dataset.mentorAsk||b.textContent;$('#assistant-form').requestSubmit()}});
  let pendingPdfText='',pendingPdfName='',pdfjsPromise=null;
  async function extractPdfText(file){if(!file||(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf'))throw new Error('Choose a PDF file.');if(file.size>25*1024*1024)throw new Error('This PDF is over 25 MB. Choose a smaller file.');if(!pdfjsPromise)pdfjsPromise=import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/6.3.289/pdf.min.mjs').then(function(lib){lib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/6.3.289/pdf.worker.min.mjs';return lib}).catch(function(err){pdfjsPromise=null;throw new Error('The PDF reader could not load. Connect to the internet once, then try again. '+err.message)});const pdfjs=await pdfjsPromise,pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;if(pdf.numPages>100)throw new Error('This PDF has '+pdf.numPages+' pages. For a focused lesson, split it into sections of 100 pages or fewer.');let text='';for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent();text+='\n\n[Page '+i+']\n'+content.items.map(function(x){return x.str||''}).join(' ');$('#mentor-pdf-status').textContent='Reading page '+i+' of '+pdf.numPages+'…';if(text.length>48000){text=text.slice(0,48000);break}}if(text.replace(/\[Page \d+\]/g,'').trim().length<80)throw new Error('This looks like a scanned/image-only PDF. ARISE can read selectable text; OCR for scanned pages is not available yet.');return {text:text,name:file.name,pages:pdf.numPages}}
  function pdfPrompt(){const mode=$('#mentor-pdf-mode').value,asks={teach:'Teach me this PDF step by step as a first-year engineering student. Start with the big picture, explain each key idea simply with a concrete example, then ask me 3 short check questions and wait for my answers.',summary:'Summarize this PDF accurately. Give me its purpose, section-by-section key ideas, important definitions or equations, and a short list of what to revise. Flag anything unclear instead of guessing.',notes:'Turn this PDF into clean exam revision notes: headings, definitions, formulas, worked-example outlines, common mistakes and 5 likely practice questions. Keep facts grounded in the document.',quiz:'Quiz me on this PDF one question at a time. Start at beginner level, wait for my answer before revealing the explanation, and adapt the next question to my response.'};return asks[mode]+' Document: '+pendingPdfName}
  $('#mentor-pdf-form').addEventListener('submit',async function(e){e.preventDefault();if(pendingPdfText){$('#assistant-form textarea').value=pdfPrompt();openAssistant();$('#assistant-form').requestSubmit();return}const file=$('#mentor-pdf-file').files[0],button=$('#mentor-pdf-submit');if(!file){$('#mentor-pdf-status').textContent='Choose a PDF first.';return}button.disabled=true;button.textContent='Reading…';$('#mentor-pdf-form').classList.remove('ready');try{const doc=await extractPdfText(file);pendingPdfText=doc.text;pendingPdfName=doc.name;$('#mentor-pdf-form').classList.add('ready');$('#mentor-pdf-status').innerHTML='<span class="pdf-ready-chip">✓ PDF ready</span>'+esc(doc.name)+' · '+doc.pages+' pages · text stays in this tab until you ask the mentor.';button.textContent='Ask ARISE';button.disabled=false}catch(err){$('#mentor-pdf-status').textContent=err.message;toast(err.message)}finally{button.disabled=false;if(button.textContent==='Reading…')button.textContent='Load PDF'}});
  $('#mentor-pdf-file').addEventListener('change',function(){const f=this.files[0];if(f){$('#mentor-pdf-status').textContent=f.name+' · '+Math.ceil(f.size/1024)+' KB · choose “Load PDF” to prepare a lesson.';$('#mentor-pdf-submit').disabled=false;$('#mentor-pdf-submit').textContent='Load PDF';pendingPdfText='';pendingPdfName='';$('#mentor-pdf-form').classList.remove('ready')}});
