  function generateSudokuSolution(seed){const rnd=seededRandom(seed),base=Array.from({length:9},(_,r)=>Array.from({length:9},(_,c)=>(r*3+Math.floor(r/3)+c)%9+1));const bands=shuffled([0,1,2],rnd),rows=[];bands.forEach(function(b){shuffled([0,1,2],rnd).forEach(function(r){rows.push(b*3+r)})});const stacks=shuffled([0,1,2],rnd),cols=[];stacks.forEach(function(b){shuffled([0,1,2],rnd).forEach(function(c){cols.push(b*3+c)})});const nums=shuffled([1,2,3,4,5,6,7,8,9],rnd);return rows.flatMap(function(r){return cols.map(function(c){return nums[base[r][c]-1]})})}
  function sudokuSolutionCount(board){const b=board.slice(),rm=Array(9).fill(0),cm=Array(9).fill(0),bm=Array(9).fill(0);for(let i=0;i<81;i++){const v=b[i];if(!v)continue;const r=Math.floor(i/9),c=i%9,m=1<<v;if((rm[r]&m)||(cm[c]&m)||(bm[Math.floor(r/3)*3+Math.floor(c/3)]&m))return 0;rm[r]|=m;cm[c]|=m;bm[Math.floor(r/3)*3+Math.floor(c/3)]|=m}let count=0;function walk(){if(count>1)return;let best=-1,opts=0,bits=10;for(let i=0;i<81;i++)if(!b[i]){const r=Math.floor(i/9),c=i%9,box=Math.floor(r/3)*3+Math.floor(c/3),mask=(~(rm[r]|cm[c]|bm[box]))&1022;let n=0;for(let x=mask;x;x&=x-1)n++;if(n<bits){best=i;opts=mask;bits=n;if(n<=1)break}}if(best<0){count++;return}if(!opts)return;const r=Math.floor(best/9),c=best%9,box=Math.floor(r/3)*3+Math.floor(c/3);for(let mask=opts;mask&&count<2;mask&=mask-1){const bit=mask&-mask,v=31-Math.clz32(bit);b[best]=v;rm[r]|=bit;cm[c]|=bit;bm[box]|=bit;walk();rm[r]^=bit;cm[c]^=bit;bm[box]^=bit;b[best]=0}}walk();return count}
  function makeSudokuPuzzle(difficulty,seed){const rng=seededRandom(seed),solution=generateSudokuSolution(seed),puzzle=solution.slice(),order=shuffled(Array.from({length:81},(_,i)=>i),rng),range=difficulty==='easy'?[36,40]:difficulty==='medium'?[43,48]:[51,55],target=range[0]+Math.floor(rng()*(range[1]-range[0]+1));let holes=0;for(const i of order){if(holes>=target)break;const old=puzzle[i];puzzle[i]=0;if(sudokuSolutionCount(puzzle)===1)holes++;else puzzle[i]=old}return {solution:solution,puzzle:puzzle}}
  function startSudoku(difficulty,force){if(sudokuClock){clearInterval(sudokuClock);sudokuClock=null}const active=localStorage.getItem(sudokuGameKey);if(!force&&active){try{const g=JSON.parse(active);if(g&&!g.won){sudokuGame=g;renderSudoku();runSudokuClock();return}}catch(_){}}const st=readSudokuStats();st.generated=(st.generated||0)+1;localStorage.setItem(sudokuStoreKey,JSON.stringify(st));const seed=((Date.now()>>>0)^Math.floor(Math.random()*0xffffffff)^st.generated*2654435761)>>>0,board=makeSudokuPuzzle(difficulty,seed);sudokuGame={id:seed.toString(36),difficulty:difficulty,solution:board.solution,puzzle:board.puzzle,values:board.puzzle.slice(),selected:0,mistakes:0,hints:0,notes:{},elapsed:0,startedAt:Date.now(),won:false};sudokuNotesMode=false;saveSudoku();renderSudoku();runSudokuClock()}
  function sudokuCandidates(i){const r=Math.floor(i/9),c=i%9,used=new Set();for(let x=0;x<9;x++){used.add(sudokuGame.values[r*9+x]);used.add(sudokuGame.values[x*9+c])}const br=Math.floor(r/3)*3,bc=Math.floor(c/3)*3;for(let y=0;y<3;y++)for(let x=0;x<3;x++)used.add(sudokuGame.values[(br+y)*9+bc+x]);return [1,2,3,4,5,6,7,8,9].filter(function(v){return !used.has(v)})}
  function renderSudoku(){if(!sudokuGame)return;const g=sudokuGame,sel=g.selected,sr=Math.floor(sel/9),sc=sel%9,sv=g.values[sel];$('#sudoku-difficulty').value=g.difficulty;$('#sudoku-mistakes').textContent=g.mistakes;$('#sudoku-puzzle-number').textContent='Generated puzzle · '+g.id+' · 1,000+ possible';$('#sudoku-board').innerHTML=g.values.map(function(v,i){const r=Math.floor(i/9),c=i%9,same=sv&&v===sv,wrong=v&&v!==g.solution[i];return '<button role="gridcell" aria-label="Row '+(r+1)+', column '+(c+1)+(v?', '+v:' blank')+'" class="sudoku-cell '+(g.puzzle[i]?'given ':'')+(i===sel?'selected ':'')+(r===sr||c===sc?'peer ':'')+(same?' same-value ':'')+(wrong?'wrong ':'')+((Math.floor(r/3)+Math.floor(c/3))%2?'box-alt ':'')+'" data-sudoku-cell="'+i+'">'+(v||'')+(g.notes[i]&&g.notes[i].length?'<small class="sudoku-pencil">'+g.notes[i].join('')+'</small>':'')+'</button>'}).join('');$('#sudoku-numpad').innerHTML='<button data-sudoku-num="0">⌫</button>'+[1,2,3,4,5,6,7,8,9].map(function(n){return '<button data-sudoku-num="'+n+'">'+n+'</button>'}).join('');$('#sudoku-timer').textContent=String(Math.floor(g.elapsed/60)).padStart(2,'0')+':'+String(g.elapsed%60).padStart(2,'0');$('#sudoku-notes-toggle').textContent='Notes mode: '+(sudokuNotesMode?'on':'off');$('#sudoku-status').textContent=g.won?'Puzzle solved! Start another when ready.':g.mistakes?'Take your time. Review the highlighted entries.':'Choose a cell, then enter a number.';const st=readSudokuStats(),todayCount=(st.daily&&st.daily[today])||0;$('#sudoku-daily-progress').textContent=todayCount+' solved today · '+(st.generated||0)+' generated in this browser';$('#sudoku-streak').textContent=(st.streak||0)+' day'+(st.streak===1?'':'s');$('#sudoku-stats').innerHTML='<div class="sudoku-stat-line"><span>Total solved</span><b>'+st.solved+'</b></div>'+['easy','medium','hard'].map(function(d){return '<div class="sudoku-stat-line"><span>'+d[0].toUpperCase()+d.slice(1)+'</span><b>'+((st.byDifficulty||{})[d]||0)+' solved</b></div>'}).join('')+'<div class="sudoku-stat-line"><span>Hints used this game</span><b>'+g.hints+'</b></div>'}
  function runSudokuClock(){if(sudokuClock)clearInterval(sudokuClock);sudokuClock=setInterval(function(){if(!sudokuGame||sudokuGame.won)return;sudokuGame.elapsed++;const x=$('#sudoku-timer');if(x)x.textContent=String(Math.floor(sudokuGame.elapsed/60)).padStart(2,'0')+':'+String(sudokuGame.elapsed%60).padStart(2,'0');if(sudokuGame.elapsed%5===0)saveSudoku()},1000)}
  function sudokuInput(n){const g=sudokuGame,i=g.selected;if(g.won||g.puzzle[i])return;const val=+n;if(sudokuNotesMode&&val){const a=g.notes[i]||[],p=a.indexOf(val);p<0?a.push(val):a.splice(p,1);g.notes[i]=a.sort();saveSudoku();renderSudoku();return}g.values[i]=val;g.notes[i]=[];if(val&&val!==g.solution[i]){g.mistakes++;$('#sudoku-mistakes').textContent=g.mistakes;$('#sudoku-status').textContent='That entry conflicts with the solution. Try checking the row, column and box.'}else $('#sudoku-status').textContent=val?'Good entry. Keep going.':'Cell cleared.';if(g.values.every(function(x,i){return x===g.solution[i]}))finishSudoku();saveSudoku();renderSudoku()}
  function finishSudoku(){const g=sudokuGame;g.won=true;const st=readSudokuStats(),wasToday=st.last===today;st.solved=(st.solved||0)+1;st.byDifficulty=st.byDifficulty||{easy:0,medium:0,hard:0};st.byDifficulty[g.difficulty]=(st.byDifficulty[g.difficulty]||0)+1;st.daily=st.daily||{};st.daily[today]=(st.daily[today]||0)+1;if(!wasToday)st.streak=st.last===iso(new Date(Date.now()-86400000))?(st.streak||0)+1:1;st.last=today;localStorage.setItem(sudokuStoreKey,JSON.stringify(st));state.logs.push({id:uid(),date:today,minutes:Math.max(1,Math.round(g.elapsed/60)),topic:'Sudoku · '+g.difficulty+' · solved'});saveSudoku();save();toast('Sudoku solved. Your practice is added to Progress.')}
  function sudokuHint(){const i=sudokuGame.selected;if(sudokuGame.puzzle[i]){$('#sudoku-status').textContent='Choose an empty square for a hint.';return}sudokuGame.values[i]=sudokuGame.solution[i];sudokuGame.hints++;$('#sudoku-status').textContent='Hint placed. Try to solve the rest unaided.';if(sudokuGame.values.every(function(x,i){return x===sudokuGame.solution[i]}))finishSudoku();saveSudoku();renderSudoku()}
  $('#sudoku-new').addEventListener('click',function(){startSudoku($('#sudoku-difficulty').value,true)});$('#sudoku-difficulty').addEventListener('change',function(){startSudoku(this.value,true)});$('#sudoku-board').addEventListener('click',function(e){const b=e.target.closest('[data-sudoku-cell]');if(b){sudokuGame.selected=+b.dataset.sudokuCell;saveSudoku();renderSudoku()}});$('#sudoku-numpad').addEventListener('click',function(e){const b=e.target.closest('[data-sudoku-num]');if(b)sudokuInput(+b.dataset.sudokuNum)});$('#sudoku-hint').addEventListener('click',sudokuHint);$('#sudoku-check').addEventListener('click',function(){const wrong=sudokuGame.values.some(function(x,i){return x&&x!==sudokuGame.solution[i]}),empty=sudokuGame.values.some(function(x){return !x});$('#sudoku-status').textContent=wrong?'There are entries to review. Check the highlighted squares.':empty?'Everything placed so far matches. Keep filling the board.':'Board complete!';renderSudoku()});$('#sudoku-notes-toggle').addEventListener('click',function(){sudokuNotesMode=!sudokuNotesMode;renderSudoku()});$('#sudoku-clear').addEventListener('click',function(){sudokuInput(0)});document.addEventListener('keydown',function(e){if(!sudokuGame||!$('#view-sudoku').classList.contains('active')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key>='1'&&e.key<='9'){e.preventDefault();sudokuInput(+e.key)}else if(['Backspace','Delete','0'].includes(e.key)){e.preventDefault();sudokuInput(0)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=sudokuGame.selected,r=Math.floor(i/9),c=i%9;sudokuGame.selected=e.key==='ArrowLeft'?r*9+Math.max(0,c-1):e.key==='ArrowRight'?r*9+Math.min(8,c+1):e.key==='ArrowUp'?Math.max(0,r-1)*9+c:Math.min(8,r+1)*9+c;renderSudoku()}});
